<?php require dirname(__DIR__) . '/partials/fields.php'; ?>
<div class="page-head"><div><h1>Global Admins</h1><div class="subtitle">Superadmins use only the main panel hostname and are never tenant users.</div></div><div class="page-actions"><button class="btn btn-primary" data-modal-open="globalAdminModal"><?= $this->fragment('icons/plus') ?> New global admin</button></div></div>
<div class="card"><div class="card-body tight"><div class="table-wrap"><table><thead><tr><th>Username</th><th>Email</th><th>Last sign-in</th><th>Status</th><th class="actions">Actions</th></tr></thead><tbody>
<?php foreach($rows as $row): $edit=array_intersect_key($row,array_flip(['id','username','email','active'])); ?>
<tr><td><strong><?= e($row['username']) ?></strong><?= (int)$row['id']===auth()->id()?' <span class="badge blue">You</span>':'' ?></td><td><?= e($row['email']?:'—') ?></td><td class="muted"><?= e($row['last_login']?format_date($row['last_login']):'Never') ?></td><td><?= $row['active']?'<span class="badge green">Active</span>':'<span class="badge gray">Disabled</span>' ?></td><td class="actions"><button class="btn btn-sm" data-modal-open="globalAdminModal" data-edit='<?= e(json_encode($edit,JSON_HEX_APOS|JSON_HEX_QUOT)) ?>'>Edit</button><?php if((int)$row['id']!==auth()->id()): ?><form method="post" action="/global-admins/<?= (int)$row['id'] ?>"><?= csrf() ?><input type="hidden" name="_method" value="DELETE"><button class="btn btn-sm btn-ghost" data-confirm-btn="Delete this global admin?">Delete</button></form><?php endif; ?></td></tr>
<?php endforeach; ?></tbody></table></div></div></div>
<div class="modal-overlay" id="globalAdminModal" hidden><div class="modal"><form method="post" action="/global-admins" id="globalAdminForm"><?= csrf() ?><div class="modal-head"><h2 id="globalAdminTitle">New global admin</h2><button type="button" class="icon-btn" data-modal-close><?= $this->fragment('icons/x') ?></button></div><div class="modal-body"><div class="form-grid"><?= field_text('username','Username','',['required'=>true,'autocomplete'=>'username']) ?><?= field_text('email','Email','',['type'=>'email']) ?><?= field_text('password','Password','',['type'=>'password','span'=>true,'autocomplete'=>'new-password','hint'=>'Minimum 8 characters. Leave blank on edit to keep it.']) ?><div class="span-2"><?= field_check('enabled','Account active',true) ?></div></div></div><div class="modal-foot"><button type="button" class="btn" data-modal-close>Cancel</button><button class="btn btn-primary" id="globalAdminSubmit">Create admin</button></div></form></div></div>
<script>(function(){var f=document.getElementById('globalAdminForm'),t=document.getElementById('globalAdminTitle'),s=document.getElementById('globalAdminSubmit');document.querySelectorAll('[data-modal-open="globalAdminModal"][data-edit]').forEach(function(b){b.addEventListener('click',function(){var d=JSON.parse(b.dataset.edit);f.action='/global-admins/'+d.id;t.textContent='Edit global admin';s.textContent='Save changes';f.elements.username.value=d.username||'';f.elements.username.readOnly=true;f.elements.email.value=d.email||'';f.elements.password.value='';f.elements.enabled.checked=Number(d.active)===1;});});document.querySelectorAll('[data-modal-open="globalAdminModal"]:not([data-edit])').forEach(function(b){b.addEventListener('click',function(){f.reset();f.action='/global-admins';f.elements.username.readOnly=false;t.textContent='New global admin';s.textContent='Create admin';});});})();</script>
